'use strict';
const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>Array.from(root.querySelectorAll(selector));
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatMoney=value=>'₩'+Math.round(value).toLocaleString('ko-KR');
let toastTimer;
function toast(message){const box=$('#toast');box.textContent=message;box.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.hidden=true,4000)}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('링크를 복사했습니다.')}catch{toast('복사 권한이 없습니다. 표시된 링크를 선택해 복사해 주세요.')}}

// Long-form book navigation, keyboard-accessible drawer, and reading position.
const chapters=$$('.chapter');const nav=$('#chapter-nav');let group='';
chapters.forEach((chapter,index)=>{if(chapter.dataset.group!==group){group=chapter.dataset.group;const label=document.createElement('div');label.className='nav-group';label.textContent=group;nav.append(label)}const a=document.createElement('a');a.href='#'+chapter.id;a.dataset.chapter=chapter.id;a.innerHTML=`<span>${String(index).padStart(2,'0')}</span>${escapeHTML(chapter.dataset.title)}`;nav.append(a)});
function setMenu(open){$('#sidebar').classList.toggle('open',open);$('#nav-overlay').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'목차 닫기':'목차 열기');if(open)$('#chapter-search').focus()}
$('#menu-toggle').addEventListener('click',()=>setMenu(!$('#sidebar').classList.contains('open')));
$('#close-menu').addEventListener('click',()=>{setMenu(false);$('#menu-toggle').focus()});$('#nav-overlay').addEventListener('click',()=>setMenu(false));
nav.addEventListener('click',event=>{if(event.target.closest('a'))setMenu(false)});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('#sidebar').classList.contains('open')){setMenu(false);$('#menu-toggle').focus()}});
$('#chapter-search').addEventListener('input',event=>{let visible=0;const query=event.target.value.trim().toLowerCase();$$('a',nav).forEach(a=>{a.hidden=!a.textContent.toLowerCase().includes(query);if(!a.hidden)visible++});$$('.nav-group',nav).forEach(el=>{let next=el.nextElementSibling,has=false;while(next&&!next.classList.contains('nav-group')){if(!next.hidden)has=true;next=next.nextElementSibling}el.hidden=!has});$('#no-chapters').hidden=visible>0});
let scrollQueued=false;
function updateReading(){const scroll=document.documentElement.scrollTop;const total=document.documentElement.scrollHeight-innerHeight;$('#progress').style.width=(total>0?scroll/total*100:0)+'%';let current=chapters[0];for(const chapter of chapters){if(chapter.getBoundingClientRect().top<200)current=chapter;else break}$$('a',nav).forEach(a=>{const active=a.dataset.chapter===current.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')});scrollQueued=false}
addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(updateReading)}},{passive:true});updateReading();
$('#print-book').addEventListener('click',()=>window.print());
let openedForPrint=[];addEventListener('beforeprint',()=>{openedForPrint=$$('details:not([open])');openedForPrint.forEach(d=>d.open=true)});addEventListener('afterprint',()=>openedForPrint.forEach(d=>d.open=false));

